import{_ as e,o as a,c as t,Q as n}from"./chunks/framework.19f61efe.js";const v=JSON.parse('{"title":"Agent Release Note","description":"","frontmatter":{},"headers":[],"relativePath":"note/agent_release_note.md","filePath":"note/agent_release_note.md"}'),l={name:"note/agent_release_note.md"},o=n('<h1 id="agent-release-note" tabindex="-1">Agent Release Note <a class="header-anchor" href="#agent-release-note" aria-label="Permalink to &quot;Agent Release Note&quot;">​</a></h1><h2 id="v2-4-8" tabindex="-1">v2.4.8 <a class="header-anchor" href="#v2-4-8" aria-label="Permalink to &quot;v2.4.8&quot;">​</a></h2><p>2025-03-13</p><ul><li>agent 优化任务锁释放逻辑，修复“至少持有 5 秒”的逻辑 bug</li><li>优化 agent 服务注册失败重试逻辑</li></ul><h2 id="v2-4-7" tabindex="-1">v2.4.7 <a class="header-anchor" href="#v2-4-7" aria-label="Permalink to &quot;v2.4.7&quot;">​</a></h2><p>2024-08-08</p><ul><li>agent 修复每次调度任务时 tmp_id 重复的问题</li><li>agent 任务运行状态上报及结束状态上报增加该任务的计划时间字段，中心会将该字段记录日志，并通过该字段的值来兜底边缘异常重复调度的问题</li></ul><h2 id="v2-4-6" tabindex="-1">v2.4.6 <a class="header-anchor" href="#v2-4-6" aria-label="Permalink to &quot;v2.4.6&quot;">​</a></h2><p>2024-04-23</p><ul><li>agent 增加权重逻辑，权重范围 0-100，超出则默认为 100，当权重设置为 0 时，该 agent 停止调度</li><li>修复 v2.4.5 版本 agent 锁实现导致可能的协程泄露问题</li></ul><h2 id="v2-4-4" tabindex="-1">v2.4.4 <a class="header-anchor" href="#v2-4-4" aria-label="Permalink to &quot;v2.4.4&quot;">​</a></h2><p>2023-10-07</p><ul><li>修复 agent 注册连接断开后，重试时没有刷新 token 的问题，在 token 过期后会出现永远无法注册成功的情况</li></ul><h2 id="v2-4-3" tabindex="-1">v2.4.3 <a class="header-anchor" href="#v2-4-3" aria-label="Permalink to &quot;v2.4.3&quot;">​</a></h2><p>2023-09-17</p><p>agent 不再需要公网环境，通过启动时服务注册建立的 gRPC Stream 双向流实现与中心服务的通信<br> 支持 windows 环境，构建需增加 -tags=windows</p>',16),r=[o];function i(s,h,_,d,c,u){return a(),t("div",null,r)}const g=e(l,[["render",i]]);export{v as __pageData,g as default};
